using System;
using System.Data;
using System.Web.UI.WebControls;
using DCore;
using CRMObject;

namespace InformationCMS.Controls.CRM.BookingLog
{
    public partial class List : ControlBase
    {
        private int PageIndex
        {
            get { return (ViewState["PageIndex"] == null) ? 1 : Convert.ToInt32(ViewState["PageIndex"]); }
            set { ViewState["PageIndex"] = value; }
        }

        private int PageSize
        {
            get
            {
                int v;
                if (ddlPageSize != null && int.TryParse(ddlPageSize.SelectedValue, out v) && v > 0)
                    return v;
                return 20;
            }
        }

        #region Permission

        protected string strPermissionView = "SYS_BookingLog_View";

        #endregion

        protected void Page_Load(object sender, EventArgs e)
        {
            SetPermission();

            if (!IsPostBack)
            {
                PageIndex = 1;
                BindData();
            }
        }

        private void SetPermission()
        {
            if (!User.IsPermissionGroup("1") && !User.IsPermission(strPermissionView))
            {
                Session[DCore.Globals.ERROR] = new SystemError("Bạn không có quyền truy cập", null, ReturnPage);
                Response.Redirect("~/" + MessagePage);
            }
        }

        private void BindData()
        {
            string keyword = (txtKeyword.Text ?? "").Trim();
            string formCode = (ddlFormCode.SelectedValue ?? "").Trim();
            string actionType = (ddlActionType.SelectedValue ?? "").Trim();
            string username = (txtUsername.Text ?? "").Trim();
            DateTime? fromDate = dtmFromDate.SelectedDate;
            DateTime? toDate = dtmToDate.SelectedDate;

            var obj = new CRM_Booking();
            DataTable dt = obj.GetDataTable(
                "SYS_BookingLog_ViewPage",
                "@Keyword", string.IsNullOrWhiteSpace(keyword) ? (object)DBNull.Value : keyword,
                "@FormCode", string.IsNullOrWhiteSpace(formCode) ? (object)DBNull.Value : formCode,
                "@ActionType", string.IsNullOrWhiteSpace(actionType) ? (object)DBNull.Value : actionType,
                "@Username", string.IsNullOrWhiteSpace(username) ? (object)DBNull.Value : username,
                "@FromDate", fromDate.HasValue ? (object)fromDate.Value : DBNull.Value,
                "@ToDate", toDate.HasValue ? (object)toDate.Value : DBNull.Value,
                "@PageIndex", PageIndex,
                "@PageSize", PageSize
            );

            int totalRows = 0;
            if (dt != null && dt.Rows.Count > 0 && dt.Columns.Contains("TotalRows"))
            {
                totalRows = Convert.ToInt32(dt.Rows[0]["TotalRows"]);
                dt.Columns.Remove("TotalRows");
            }

            int totalPage = (totalRows <= 0) ? 1 : (int)Math.Ceiling(totalRows / (double)PageSize);
            if (PageIndex > totalPage)
                PageIndex = Math.Max(1, totalPage);

            if (dt != null)
            {
                if (!dt.Columns.Contains("RowNum"))
                    dt.Columns.Add("RowNum", typeof(int));

                int start = (PageIndex - 1) * PageSize;
                for (int i = 0; i < dt.Rows.Count; i++)
                    dt.Rows[i]["RowNum"] = start + i + 1;
            }

            litTotal.Text = totalRows.ToString("N0");
            litPage.Text = PageIndex.ToString();
            litTotalPage.Text = totalPage.ToString();

            btnPrev.Enabled = PageIndex > 1;
            btnNext.Enabled = PageIndex < totalPage;

            rptLog.DataSource = dt;
            rptLog.DataBind();

            phEmpty.Visible = (dt == null || dt.Rows.Count == 0);

            udpList.Update();
        }

        protected string FormatCountSummary(object totalRows, object addCount, object updateCount)
        {
            return string.Format("{0}/{1}/{2}",
                FormatNullableInt(totalRows),
                FormatNullableInt(addCount),
                FormatNullableInt(updateCount));
        }

        protected string FormatSuccess(object isSuccess, object errorMessage)
        {
            bool ok = false;
            if (isSuccess != null && isSuccess != DBNull.Value)
                ok = Convert.ToBoolean(isSuccess);

            if (ok)
                return "<span class=\"text-success\">OK</span>";

            string msg = errorMessage != null && errorMessage != DBNull.Value ? errorMessage.ToString() : "Lỗi";
            if (msg.Length > 40)
                msg = msg.Substring(0, 40) + "...";

            return string.Format("<span class=\"text-danger\" title=\"{0}\">Lỗi</span>", Server.HtmlEncode(msg));
        }

        private string FormatNullableInt(object value)
        {
            if (value == null || value == DBNull.Value)
                return "-";

            return Convert.ToInt32(value).ToString();
        }

        protected void btnSearch_Click(object sender, EventArgs e)
        {
            PageIndex = 1;
            BindData();
            WebGlobal.MessageManager.ShowMessage(Page, "Đã tải dữ liệu logs.");
        }

        protected void btnClear_Click(object sender, EventArgs e)
        {
            txtKeyword.Text =";
            txtUsername.Text =";
            dtmFromDate.SelectedDate = null;
            dtmToDate.SelectedDate = null;
            ddlFormCode.SelectedValue =";
            ddlActionType.SelectedValue =";
            if (ddlPageSize != null)
                ddlPageSize.SelectedValue = "20";
            PageIndex = 1;
            BindData();
            WebGlobal.MessageManager.ShowMessage(Page, "Đã làm mới bộ lọc.");
        }

        protected void btnPrev_Click(object sender, EventArgs e)
        {
            if (PageIndex > 1)
            {
                PageIndex--;
                BindData();
            }
        }

        protected void btnNext_Click(object sender, EventArgs e)
        {
            PageIndex++;
            BindData();
        }

        protected void ddlPageSize_SelectedIndexChanged(object sender, EventArgs e)
        {
            PageIndex = 1;
            BindData();
        }
    }
}

